import {speechFor} from '../shared/speech.mjs';
import {SpeechButton} from './SpeechButton';
import {useEffect, useRef, useState} from 'react';
import {BookOpen, Check, ChevronLeft, ChevronRight, Download, Eye, FileText, ImagePlus, Layers, Plus, Save, Settings2, ShieldCheck, Sparkles, Square, Trash2, Undo2} from 'lucide-react';
import {api, downloadJSON, readImport} from './api';
import type {StudioProps} from './types';
import {Button, Empty, Field, ImportButton, Modal, SectionHeader, Spinner, TextContent, Toggle} from './UI';
import {asEpisodeDraft, draftHasChanges, draftSavePayload, fanficStorageKey, persistEpisodeDraft, restoreEpisodeDraft, sameDraftScope, type EpisodeDraft} from './fanficDrafts';
import {calibrationCheckLabels, episodeFactRecords, editableFact, factLabels, factSavePayload, fanficPanels, proposalState, profileUpdatePayload, rebaseMetadataDraft, resumableEpisode, reviewIsCurrent, stageDisplay, stageLabels, type FanficPanel} from './fanficWorkbench';
import './fanfic.css';

const projectPath=(id:string)=>'/fanfic/projects/'+encodeURIComponent(id);
const episodePath=(projectId:string,episodeId:string)=>projectPath(projectId)+'/episodes/'+encodeURIComponent(episodeId);
const asDraft=asEpisodeDraft;
const statusNames:Record<string,string>={draft:'Черновик',generating:'Генерация',running:'Генерация',ready:'Готов к чтению',complete:'Готов к чтению',done:'Готов к чтению',approved:'В каноне',stopped:'Остановлен',error:'Нужна проверка'};
const plural=(n:number,one:string,few:string,many:string)=>n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;
const filename=(value:string)=>value.replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,120)||'Фанфик';
function downloadText(text:string,name:string,type='text/plain'){
  const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));
  const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

export function FanficView({state,flush,refresh,notify,task}:StudioProps){
  const projects:any[]=(state as any).fanficProjects||[];
  const [selectedProject,setSelectedProject]=useState(()=>localStorage.getItem('sas-fanfic-project')||'');
  const [selectedEpisode,setSelectedEpisode]=useState(()=>localStorage.getItem('sas-fanfic-episode')||'');
  const [season,setSeason]=useState<number|''>('');
  const project=projects.find(p=>p.id===selectedProject)||projects[0];
  const episodes:any[]=[...(project?.episodes||[])].sort((a,b)=>a.season-b.season||a.number-b.number);
  const seasons:number[]=[...new Set<number>(episodes.map(e=>Number(e.season)||1))];
  const filteredEpisodes=season===''?episodes:episodes.filter(e=>e.season===season);
  const episode=filteredEpisodes.find(e=>e.id===selectedEpisode)||filteredEpisodes[0];
  const [draft,setDraft]=useState<EpisodeDraft|null>(null),draftRef=useRef<EpisodeDraft|null>(null);
  const [pending,setPending]=useState(false),pendingRef=useRef(false),[settings,setSettings]=useState<'new'|'edit'|null>(null),[newEpisode,setNewEpisode]=useState(false);
  const [deleting,setDeleting]=useState<'project'|'episode'|null>(null),[instruction,setInstruction]=useState('');
  const [selection,setSelection]=useState({start:0,end:0}),[editing,setEditing]=useState(false);
  const [imageOpen,setImageOpen]=useState(false),[imageInstructions,setImageInstructions]=useState(''),[imagePrompt,setImagePrompt]=useState('');
  const [imageScope,setImageScope]=useState<'recent'|'selection'>('recent'),[imageSource,setImageSource]=useState<any>(null);
  const [reading,setReading]=useState(()=>localStorage.getItem('sas-fanfic-reading')==='true');
  const [contextPreview,setContextPreview]=useState<any>(null),[material,setMaterial]=useState<any>(null);
  const [memoryEditing,setMemoryEditing]=useState(false),[factsEditing,setFactsEditing]=useState(false),[memorySnapshot,setMemorySnapshot]=useState<any>(null);
  const [workPanel,setWorkPanel]=useState<FanficPanel>('text'),[editOpen,setEditOpen]=useState(false);
  const seenProposal=useRef('');
  const [framePassport,setFramePassport]=useState<any>(null),[passportDirty,setPassportDirty]=useState(false),[passportStale,setPassportStale]=useState(false),[usePassport,setUsePassport]=useState(false),[passportSource,setPassportSource]=useState<any>(null);
  const [discardingDraft,setDiscardingDraft]=useState(false);
  const [storageFailed,setStorageFailed]=useState(false);
  const editorRef=useRef<HTMLTextAreaElement>(null);
  const running=task?.status==='running'&&(task as any).fanficProjectId===project?.id&&(task as any).episodeId===episode?.id;
  const locked=pending||task?.status==='running';
  const projectTask=task?.status==='running'&&(task as any).fanficProjectId===project?.id&&!(task as any).episodeId;
  const activeDraft=project&&episode&&sameDraftScope(draft,project.id,episode.id)?draft:null;
  const dirty=!!activeDraft?.dirty;
  const conflict=dirty&&activeDraft?.revision!==episode?.revision;
  const content=activeDraft?.content??episode?.content??'';
  const images=(state.images as any[]).filter(image=>image.fanficProjectId===project?.id&&image.episodeId===episode?.id);
  const resetPanels=()=>{setEditOpen(false);setFactsEditing(false);setMemorySnapshot(null);setWorkPanel('text');setContextPreview(null);setMaterial(null);setMemoryEditing(false);setImageOpen(false);setSettings(null);setNewEpisode(false);setDeleting(null);setDiscardingDraft(false);};
  const chooseProject=(id:string)=>{setSelectedProject(id);setSelectedEpisode(localStorage.getItem('sas-fanfic-episode-'+id)||'');setSeason('');resetPanels();localStorage.setItem('sas-fanfic-project',id);};
  const chooseEpisode=(id:string,projectId=project?.id)=>{setSelectedEpisode(id);resetPanels();localStorage.setItem('sas-fanfic-episode',id);if(projectId)localStorage.setItem('sas-fanfic-episode-'+projectId,id);};
  const putDraft=(value:EpisodeDraft)=>{draftRef.current=value;setDraft(value);setStorageFailed(!persistEpisodeDraft(sessionStorage,value));};
  useEffect(()=>{
    if(!episode){draftRef.current=null;setDraft(null);return;}
    if(!sameDraftScope(draftRef.current,project.id,episode.id)){
      const next=restoreEpisodeDraft(sessionStorage,project.id,episode);
      draftRef.current=next;setDraft(next);setStorageFailed(next.dirty&&!persistEpisodeDraft(sessionStorage,next));setSelection({start:0,end:0});
      setInstruction(sessionStorage.getItem(fanficStorageKey('instruction',project.id,episode.id))||sessionStorage.getItem('sas-fanfic-instruction-'+episode.id)||'');setEditing(!!next.dirty);
      setImagePrompt('');setImageSource(null);setFramePassport(null);setPassportSource(null);setPassportDirty(false);setPassportStale(false);setUsePassport(false);setImageScope('recent');setImageInstructions('');setImageOpen(false);setContextPreview(null);setMemoryEditing(false);setFactsEditing(false);setMemorySnapshot(null);setMaterial(null);
    }else if(!draftRef.current?.dirty){const next=asDraft(project.id,episode);draftRef.current=next;setDraft(next);}
  },[project?.id,episode?.id,episode?.revision,episode?.content,episode?.brief,episode?.title,episode?.season,episode?.number]);
  useEffect(()=>{const id=project?.id+':'+episode?.id+':'+episode?.editProposal?.id;if(episode?.editProposal&&seenProposal.current!==id){seenProposal.current=id;setEditOpen(true);setWorkPanel('text');}},[project?.id,episode?.id,episode?.editProposal?.id]);
  useEffect(()=>{setContextPreview(null);},[project?.updatedAt,episode?.revision,instruction]);
  useEffect(()=>{if(imageSource&&imageSource.sourceRevision!==episode?.revision){setImagePrompt('');setImageSource(null);}},[episode?.revision]);
  useEffect(()=>{
    const warn=(event:BeforeUnloadEvent)=>{if(draftRef.current?.dirty){event.preventDefault();event.returnValue='';}};
    window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);
  },[]);
  useEffect(()=>{
    const open=(event:Event)=>{const detail=(event as CustomEvent).detail||{};if(detail.projectId){chooseProject(detail.projectId);if(detail.episodeId)chooseEpisode(detail.episodeId,detail.projectId);}};
    window.addEventListener('sas-fanfic-open',open);return()=>window.removeEventListener('sas-fanfic-open',open);
  },[]);
  const changeDraft=(patch:Partial<EpisodeDraft>)=>{if(activeDraft){const next={...activeDraft,...patch};putDraft({...next,dirty:draftHasChanges(next,episode)});setContextPreview(null);setImagePrompt('');setImageSource(null);}};
  const changeInstruction=(value:string)=>{setInstruction(value);if(episode)try{sessionStorage.setItem(fanficStorageKey('instruction',project.id,episode.id),value);sessionStorage.removeItem('sas-fanfic-instruction-'+episode.id);}catch{notify('Пожелание остаётся на экране, но браузер не смог сохранить его черновик.',true);}};
  const perform=async(work:()=>Promise<void>)=>{if(pendingRef.current)return;pendingRef.current=true;setPending(true);try{await flush();await work();await refresh();}catch(error:any){notify(error.message,true);await refresh().catch(()=>{});}finally{pendingRef.current=false;setPending(false);}};
  const saveDraft=async()=>{
    const current=draftRef.current;
    if(!project||!episode)throw new Error('Выберите эпизод.');
    if(!sameDraftScope(current,project.id,episode.id))throw new Error('Выбран другой эпизод. Повторите действие после загрузки его текста.');
    if(!current?.dirty)return episode;
    const saved=await api(episodePath(current.projectId,current.id),draftSavePayload(current),'PATCH');
    if(sameDraftScope(draftRef.current,current.projectId,current.id))putDraft(asDraft(current.projectId,saved));return saved;
  };
  const generate=(action:string,selected=false)=>void perform(async()=>{
    const saved=await saveDraft();
    const body:any={action,expectedRevision:saved.revision};
    if(instruction.trim())body.instructions=instruction.trim();
    if(action==='rewrite'){body.preview=true;body.selectionStart=selected?selection.start:0;body.selectionEnd=selected?selection.end:saved.content.length;}
    await api(episodePath(project.id,episode.id)+'/generate',body);
    setEditing(false);if(action!=='approve'&&action!=='resume')changeInstruction('');
  });
  const exportBook=(markdown:boolean)=>void perform(async()=>{
    if(dirty)await saveDraft();
    const result=await api(projectPath(project.id)+'/export');const book=result.project||result;
    const text=[markdown?'# '+book.title:book.title,...[...(book.episodes||[])].sort((a:any,b:any)=>a.season-b.season||a.number-b.number).map((item:any)=>(markdown?'## ':'')+`Сезон ${item.season} · Эпизод ${item.number} — ${item.title}\n\n${item.content||''}`)].join('\n\n');
    downloadText(text,filename(book.title)+(markdown?'.md':'.txt'),markdown?'text/markdown':'text/plain');
  });
  const canonEpisodes=episodes.filter(item=>item.status==='approved'&&!item.needsReview&&item.memory);
  const priorEpisodes=canonEpisodes.filter(item=>item.season<episode?.season||item.season===episode?.season&&item.number<episode?.number);
  const episodeIndex=filteredEpisodes.findIndex(item=>item.id===episode?.id);
  const connection=state.connections.find(item=>item.id===(project?.settings.connectionId||state.activeConnectionId));
  const draftBackup=()=>{if(activeDraft)downloadJSON({spec:'sas_fanfic_episode_draft_v1',projectTitle:project.title,episode:activeDraft},filename(project.title)+'-'+activeDraft.season+'.'+activeDraft.number+'-черновик.json');};
  const wordCount=(content.match(/[\p{L}\p{N}]+(?:[-’'][\p{L}\p{N}]+)*/gu)||[]).length;
  const proposal=proposalState(episode,content,dirty);
  const facts=episodeFactRecords(episodes,episode?{...episode,projectId:project.id}:null);
  const review=episode?.continuityReview;
  const currentPassport=framePassport?.projectId===project?.id&&framePassport?.episodeId===episode?.id?framePassport:null;
  const passportIsStale=passportStale||!!currentPassport&&currentPassport.sourceRevision!==episode?.revision;
  const changePassport=(value:any)=>{setFramePassport(value);setPassportDirty(true);setImagePrompt('');setImageSource(null);};
  const toggleReading=()=>{setWorkPanel('text');if(!reading)setEditing(false);else if(dirty)setEditing(true);setReading(value=>{localStorage.setItem('sas-fanfic-reading',String(!value));return !value;});};
  return <div className={'page fanfic-page'+(reading?' fanfic-reading':'')}>
    <SectionHeader eyebrow="АВТОРСКАЯ МАСТЕРСКАЯ" title="Фанфик" description="Создавайте эпизоды, редактируйте текст и сохраняйте события в каноне своего произведения." actions={<><ImportButton disabled={locked} onFile={file=>void perform(async()=>{const input=await readImport(file);const result=await api('/fanfic/import',{project:typeof input==='object'&&input!==null&&'project' in input?input.project:input});chooseProject((result.project||result).id);notify('Произведение импортировано.');})}/><Button primary disabled={locked} onClick={()=>setSettings('new')}><Plus size={16}/>Новое произведение</Button></>}/>
    {project?<>
      <div className="fanfic-project-bar"><Field label="Произведение"><select disabled={pending} value={project.id} onChange={event=>chooseProject(event.target.value)}>{projects.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select></Field><Button onClick={()=>setSettings('edit')}><Settings2 size={16}/>Настройки</Button><Button title="Удалить произведение" danger disabled={locked} onClick={()=>setDeleting('project')}><Trash2 size={16}/></Button></div>
      <section className="fanfic-book-cover" aria-label="Обзор произведения"><div className="fanfic-book-mark"><BookOpen size={28}/></div><div className="fanfic-book-title"><span className="eyebrow">ВАШЕ ПРОИЗВЕДЕНИЕ</span><h2>{project.title}</h2><p>{[project.settings.genre,project.settings.perspective,project.settings.tense].filter(Boolean).join(' · ')}</p></div><div className="fanfic-book-stats"><span><strong>{seasons.length}</strong> {plural(seasons.length,'сезон','сезона','сезонов')}</span><span><strong>{episodes.length}</strong> {plural(episodes.length,'серия','серии','серий')}</span><span><strong>{canonEpisodes.length}</strong> в каноне</span></div></section>
      <div className="fanfic-work-status"><span><Sparkles size={14}/>{connection?.model||connection?.name||'Модель не выбрана'}<small>{connection?.contextWindow?`${connection.contextWindow.toLocaleString('ru-RU')} токенов контекста`:''}</small></span><span><ShieldCheck size={14}/>Память «{project.title}»<small>Отдельная от РП и мультиплеера</small></span></div>
      {projectTask&&<div className="fanfic-progress" role="status"><Spinner/><span>{task?.stage||'Проверяем модель для фанфика…'}<small>Контрольные задания не изменяют текст и память произведения.</small></span><Button onClick={()=>api('/tasks/stop',{}).catch(error=>notify(error.message,true))}>Остановить</Button></div>}
      {episode&&<nav className="fanfic-workbench-tabs" aria-label="Разделы мастерской">{fanficPanels.map(panel=><button key={panel.id} type="button" aria-pressed={workPanel===panel.id} aria-controls={'fanfic-panel-'+panel.id} onClick={()=>{setReading(false);localStorage.setItem('sas-fanfic-reading','false');setWorkPanel(panel.id);}}>{panel.label}{panel.id==='canon'&&review?.issues?.length>0&&<span>{review.issues.length}</span>}</button>)}</nav>}
      {!episode&&<div className="fanfic-episode-bar"><Field label="Сезон"><select disabled={pending} value={season} onChange={event=>{setSeason(event.target.value?Number(event.target.value):'');setSelectedEpisode('');}}><option value="">Все сезоны</option>{seasons.map(value=><option key={value} value={value}>Сезон {value}</option>)}</select></Field><Field label="Эпизод"><select disabled={pending} value={episode?.id||''} onChange={event=>chooseEpisode(event.target.value)}>{!filteredEpisodes.length&&<option value="">Нет эпизодов</option>}{filteredEpisodes.map(item=><option key={item.id} value={item.id}>{item.season}.{item.number} · {item.title}{item.needsReview?' · требует проверки':item.status==='approved'?' · в каноне':''}</option>)}</select></Field><Button disabled={locked} onClick={()=>setNewEpisode(true)}><Plus size={16}/>Новый эпизод</Button></div>}
      {episode&&<nav className="fanfic-episode-navigation" aria-label="Переход между эпизодами"><Button disabled={pending||episodeIndex<=0} onClick={()=>chooseEpisode(filteredEpisodes[episodeIndex-1].id)}><ChevronLeft size={16}/>Предыдущий</Button><span>{episodeIndex+1} / {filteredEpisodes.length}</span><Button disabled={pending||episodeIndex>=filteredEpisodes.length-1} onClick={()=>chooseEpisode(filteredEpisodes[episodeIndex+1].id)}>Следующий<ChevronRight size={16}/></Button></nav>}
      {episode?<div className="fanfic-workspace" data-panel={workPanel}>
        <aside id="fanfic-panel-series" className="fanfic-timeline panel" aria-label="Сезоны и серии"><div className="fanfic-episode-bar"><Field label="Сезон"><select disabled={pending} value={season} onChange={event=>{setSeason(event.target.value?Number(event.target.value):'');setSelectedEpisode('');}}><option value="">Все сезоны</option>{seasons.map(value=><option key={value} value={value}>Сезон {value}</option>)}</select></Field><Field label="Эпизод"><select disabled={pending} value={episode?.id||''} onChange={event=>chooseEpisode(event.target.value)}>{!filteredEpisodes.length&&<option value="">Нет эпизодов</option>}{filteredEpisodes.map(item=><option key={item.id} value={item.id}>{item.season}.{item.number} · {item.title}{item.needsReview?' · требует проверки':item.status==='approved'?' · в каноне':''}</option>)}</select></Field><Button disabled={locked} onClick={()=>setNewEpisode(true)}><Plus size={16}/>Новый эпизод</Button></div>{!!episodes.length&&<details className="fanfic-toc" open><summary><Layers size={15}/>Хронология · {episodes.length} серий</summary><nav aria-label="Оглавление фанфика">{(season===''?seasons:[season]).map(value=><section key={value}><h4>Сезон {value}</h4><div className="fanfic-chapters">{episodes.filter(item=>item.season===value).map(item=><button key={item.id} type="button" aria-current={item.id===episode?.id?'page':undefined} disabled={pending} onClick={()=>chooseEpisode(item.id)}><span className="fanfic-chapter-number">{String(item.number).padStart(2,'0')}</span><span><strong>{item.title||`Эпизод ${item.number}`}</strong><small>{item.needsReview?'Проверить канон':statusNames[item.status]||'Черновик'}</small></span>{item.status==='approved'&&!item.needsReview&&<Check size={15}/>}</button>)}</div></section>)}</nav></details>}<p className="muted small">Утверждённые серии образуют канон. Черновики остаются вне памяти следующих серий.</p></aside>
        <main id="fanfic-panel-text" className="fanfic-manuscript panel">
          <div className="fanfic-manuscript-heading"><div><span className="eyebrow">СЕЗОН {activeDraft?.season??episode.season} · ЭПИЗОД {activeDraft?.number??episode.number}</span><h2>{activeDraft?.title||episode.title||`Эпизод ${episode.number}`}</h2><p className="fanfic-writing-meta">{wordCount.toLocaleString('ru-RU')} {plural(wordCount,'слово','слова','слов')} · {Math.max(1,Math.ceil(wordCount/200))} мин чтения{dirty?' · правки только в черновике':''}</p></div><div className="fanfic-manuscript-tools"><span className={'badge '+(episode.status==='approved'&&!episode.needsReview&&!dirty?'positive':'')}>{dirty?'Есть ручные правки':episode.needsReview?'Проверить канон':statusNames[episode.status]||'Черновик'}</span><Button onClick={toggleReading} title={reading?'Вернуться в мастерскую':'Скрыть инструменты для чтения'}><Eye size={15}/>{reading?'Мастерская':'Читать'}</Button></div></div>
          {episode.needsReview&&<p className="fanfic-notice">Предыдущий эпизод изменён. Проверьте согласованность событий и подтвердите этот эпизод заново.</p>}
          {episode.error&&!running&&<p className="error-box" role="alert">{episode.error}</p>}
          {conflict&&<div className="error-box" role="alert"><p>Сохранённая серия изменилась в другом окне. Ваши правки остаются в черновике и не перезаписывают её.</p><div className="fanfic-toolbar"><Button onClick={draftBackup}><Download size={15}/>Скачать свои правки</Button><Button disabled={locked} onClick={()=>setDiscardingDraft(true)}>Открыть сохранённую версию</Button></div></div>}
          {storageFailed&&<p className="error-box" role="alert">Браузер не смог сохранить резервный черновик. До смены вкладки сохраните правки или скачайте их.</p>}
          <details className="fanfic-brief" open={!content}><summary>Задание эпизода</summary><Field label="События, реплики и пожелания автора" hint="Пожелания редактору и P.S. отделены от событий произведения."><textarea rows={4} maxLength={16000} disabled={locked} value={activeDraft?.brief??episode.brief??''} onChange={event=>changeDraft({brief:event.target.value})} placeholder="Сезон 1, эпизод 1. Герои прибывают в незнакомый город…\nP.S. Повествование от третьего лица, атмосферное начало."/></Field><details><summary>Название и нумерация</summary><div className="fanfic-number-fields"><Field label="Название эпизода"><input disabled={locked} maxLength={200} value={activeDraft?.title??episode.title} onChange={event=>changeDraft({title:event.target.value})}/></Field><Field label="Сезон"><input disabled={locked} type="number" min={1} max={999} value={activeDraft?.season??episode.season} onChange={event=>changeDraft({season:Number(event.target.value)})}/></Field><Field label="Номер"><input disabled={locked} type="number" min={1} max={9999} value={activeDraft?.number??episode.number} onChange={event=>changeDraft({number:Number(event.target.value)})}/></Field></div></details></details>
          <div className="fanfic-toolbar">
            {!content&&<Button primary disabled={locked||conflict||!(activeDraft?.brief??episode.brief)?.trim()} onClick={()=>generate('write')}><Sparkles size={16}/>Написать эпизод</Button>}
            {!!content&&<><Button primary disabled={locked||conflict} onClick={()=>generate('continue')}><Sparkles size={16}/>Продолжить</Button><Button disabled={locked||conflict} onClick={()=>generate('alternative')}>Другой вариант</Button></>}
            <Button disabled={locked} onClick={()=>setEditing(!editing)}>{editing?'Читать':'Редактировать текст'}</Button>
            {resumableEpisode(episode)&&<Button primary disabled={locked||conflict} onClick={()=>generate('resume')}>{episode.generation.preview?'Продолжить подготовку правки':episode.generation.action==='review'?'Продолжить проверку связности':'Продолжить с сохранённого этапа'}</Button>}
            {dirty&&<><Button disabled={locked||conflict} onClick={()=>void perform(async()=>{await saveDraft();notify('Правки сохранены.');})}><Save size={16}/>Сохранить правки</Button><Button onClick={draftBackup} title="Скачать резервный черновик"><Download size={15}/>Черновик</Button><Button disabled={locked} onClick={()=>setDiscardingDraft(true)}><Undo2 size={16}/>Сбросить правки</Button></>}
            {running&&<Button onClick={()=>api('/tasks/stop',{}).catch(error=>notify(error.message,true))}><Square size={16}/>Остановить</Button>}
          </div>
          {running&&<div className="fanfic-progress" role="status"><Spinner/><span>{task?.stage||'Генерация эпизода…'}<small>Можно открыть другую вкладку — готовый текст сохраняется.</small></span>{reading&&<Button onClick={()=>api('/tasks/stop',{}).catch(error=>notify(error.message,true))}>Остановить</Button>}</div>}
          {task?.status==='running'&&!running&&!projectTask&&<p className="fanfic-notice" role="status">Сейчас выполняется другая генерация. Эту серию можно читать; изменение текста станет доступно после её завершения.</p>}
          {dirty&&!conflict&&!storageFailed&&<p className="fanfic-draft-note" role="status">Черновик сохранён в этой вкладке браузера. Перед генерацией правки сохранятся в произведение.</p>}
          {(state.plugins||[]).some(p=>p.id==='tts'&&p.enabled)&&content?.trim()&&<div className="row"><SpeechButton id={`fanfic:${project.id}:${episode.id}`} text={content} settings={speechFor(state.settings.speech,{fanfic:true})} notify={notify}/><span className="small muted">Озвучить серию</span></div>}
          {editing&&!reading?<><textarea ref={editorRef} aria-label="Текст эпизода" className="fanfic-text-editor" disabled={locked} maxLength={2000000} value={content} onChange={event=>changeDraft({content:event.target.value})} onSelect={event=>setSelection({start:event.currentTarget.selectionStart,end:event.currentTarget.selectionEnd})}/><p className="muted small">Выделите фрагмент, чтобы переписать только его или создать по нему иллюстрацию. Остальной текст останется на месте.</p></>:content?<article className="fanfic-prose" aria-label="Текст эпизода"><TextContent text={content}/></article>:<div className="fanfic-blank"><BookOpen size={36}/><h3>Начните с замысла</h3><p>Опишите события в задании эпизода. Сначала появится план, затем — текст каждой сцены.</p></div>}
          {!!content&&<div className="fanfic-approval"><Button primary disabled={locked||conflict||(episode.status==='approved'&&!episode.needsReview&&!dirty)} onClick={()=>generate('approve')}><Check size={16}/>{episode.status==='approved'&&!episode.needsReview&&!dirty?'События сохранены в каноне':'Утвердить эпизод и память'}</Button><span className="muted small">После ручной правки память серии нужно утвердить заново.</span></div>}
          {episode.editProposal&&<div className="fanfic-notice"><strong>Редактор подготовил предложение.</strong><p className="small">Исходный текст остаётся сохранённым до вашего принятия правки.</p><Button disabled={locked} onClick={()=>setEditOpen(true)}>Сравнить и принять или отклонить</Button></div>}<details className="fanfic-editor-chat" open><summary>Правки и пожелания редактору</summary><div className="fanfic-editor-messages">{(episode.editorMessages||[]).map((message:any,index:number)=><article key={message.id||index} className={'fanfic-editor-message '+message.role}><strong>{message.role==='user'?'Автор':'Редактор'}</strong><TextContent text={message.content}/></article>)}</div><textarea aria-label="Пожелания редактору" rows={2} disabled={locked} maxLength={8000} value={instruction} onChange={event=>changeInstruction(event.target.value)} placeholder="Сделай диалог сдержаннее, сохрани события и точку зрения…"/><div className="fanfic-toolbar"><Button disabled={locked||!content||!instruction.trim()} onClick={()=>generate('rewrite')}>Предложить правку эпизода</Button><Button disabled={locked||!editing||selection.end<=selection.start||!instruction.trim()} onClick={()=>generate('rewrite',true)}>Предложить правку выделенного{selection.end>selection.start?` (${selection.end-selection.start})`:''}</Button></div></details>
        </main>
        <aside id="fanfic-panel-canon" className="fanfic-inspector" aria-label="Канон и инструменты произведения">
          <section className="panel fanfic-materials"><h3><BookOpen size={16}/>Герои и мир</h3><div className="fanfic-material-chips">{[...(project.characters||[]),...(project.personas||[])].map((card:any)=><button type="button" key={card.id} onClick={()=>setMaterial({kind:'card',...card})}><span className="fanfic-mini-avatar">{card.avatar?.startsWith('data:image/')||card.avatar?.startsWith('http')?<img src={card.avatar} alt=""/>:card.avatar||'✦'}</span>{card.name}</button>)}</div><div className="fanfic-material-books">{(project.lorebooks||[]).map((book:any)=><button type="button" key={book.id} onClick={()=>setMaterial({kind:'lore',...book})}><Layers size={14}/><span>{book.name}<small>{book.entries?.filter((entry:any)=>entry.enabled!==false).length||0} активных записей</small></span></button>)}</div>{!project.characters?.length&&!project.personas?.length&&!project.lorebooks?.length&&<p className="muted small">Добавьте героев и лорбуки в настройках произведения.</p>}<Button disabled={locked} onClick={()=>setSettings('edit')}>Настроить материалы</Button></section>
          <section className="panel fanfic-review"><h3><ShieldCheck size={16}/>Связность сюжета</h3><Button disabled={locked||conflict||!content} onClick={()=>generate('review')}><Eye size={15}/>Проверить серию</Button>{review?<><p className="muted small">{reviewIsCurrent(episode,dirty)?review.status==='unavailable'?'Проверка недоступна: замечания не получены.':review.issues?.length?'Есть места для авторской проверки.':'Противоречий не найдено в доступном контексте.':'Проверка относится к предыдущей версии текста.'}</p>{review.error&&<p className="error-box small">{review.error}</p>}{review.warnings?.map((warning:string,i:number)=><p className="fanfic-notice small" key={i}>{warning}</p>)}<div className="fanfic-review-list">{review.issues?.map((issue:any,i:number)=><details key={i}><summary><span className={'badge '+(issue.severity==='error'?'fanfic-issue-error':'fanfic-issue-warning')}>{issue.severity==='error'?'Противоречие':'Проверить'}</span>{issue.message}</summary>{issue.evidence?.map((quote:string,j:number)=><blockquote key={j}>{quote}</blockquote>)}{issue.suggestion&&<p><strong>Предложение: </strong>{issue.suggestion}</p>}<p className="muted small">Замечание не изменяет текст и канон автоматически.</p></details>)}</div></>:<p className="muted small">Проверка сопоставляет серию с доступными фактами этого произведения; решение остаётся за автором.</p>}</section>
          <section className="panel fanfic-facts"><h3>Факты и источники</h3><p className="muted small">Обещания, отношения, предметы и другие факты до текущего момента хронологии.</p>{episode.memory&&<Button disabled={locked||dirty} onClick={()=>{setMemorySnapshot(structuredClone(episode.memory));setFactsEditing(true);}}>Редактировать факты этой серии</Button>}<div className="fanfic-fact-list">{facts.map(({fact,episode:source,eligible},i)=><details key={fact.id||i}><summary><span className="badge">{factLabels[fact.type]||'Факт'}</span>{fact.subject}{fact.authorConfirmed&&fact.predicate?' · '+fact.predicate:''}</summary><p>{fact.value}</p><small>{source.season}.{source.number} · {source.title} · {eligible?'Доступен текущей сцене':source.id===episode.id?'Для следующих серий':'Требует утверждения'}</small>{fact.evidence?.map((e:any,j:number)=><blockquote key={j}>{e.quote}</blockquote>)}<span className="fanfic-memory-caption">{fact.authorConfirmed?'Подтверждён автором':'Извлечено моделью; сверено с цитатой'}</span></details>)}{!facts.length&&<p className="muted small">Структурированные факты появятся после утверждения новой памяти серии.</p>}</div></section>
          <section className="panel fanfic-stage-profiles"><h3>Профили этапов</h3><p className="muted small">{({generic:'Базовый',dense:'Dense',moe:'MoE'} as Record<string,string>)[project.settings.generationProfiles?.modelKind||'generic']} · параметры этого произведения</p>{Object.entries(stageLabels).map(([stage,label])=>{const p=stageDisplay(project.settings,stage,connection?.contextWindow||8192);return <div key={stage}><strong>{label}</strong><span>{p.maxTokens?`до ${p.maxTokens} токенов`:'по профилю'} · {p.temperature!==undefined?`T ${p.temperature}`:'температура этапа'}</span></div>;})}<Button disabled={locked} onClick={()=>setSettings('edit')}>Настроить этапы</Button></section>
          <section className="panel"><h3>План эпизода</h3>{episode.outline?.length?<ol className="fanfic-outline">{episode.outline.map((scene:any,index:number)=><li key={index} className={index<(episode.sceneIndex||0)?'finished':''}><strong>{scene.title}</strong><p>{scene.summary}</p></li>)}</ol>:<p className="muted small">План появится перед написанием сцен.</p>}</section>
          <section className="panel fanfic-continuity"><h3><ShieldCheck size={16}/>Память произведения</h3><p className="muted small">Для этой серии доступны только утверждённые события более ранних серий «{project.title}».</p><div className="fanfic-memory-mode"><span className="badge">{project.settings.vectorMemory?'Векторная + хронология':'Хронология'}</span><span className="muted small">{priorEpisodes.length} {plural(priorEpisodes.length,'ранняя серия','ранние серии','ранних серий')}</span></div><Button disabled={locked||dirty} onClick={()=>void perform(async()=>{const result=await api(episodePath(project.id,episode.id)+'/context',{instructions:instruction});setContextPreview({...result,projectTitle:project.title,episodeTitle:episode.title,season:episode.season,number:episode.number});})}><Eye size={15}/>Проверить контекст</Button>{dirty&&<p className="muted small">Сохраните правки для проверки контекста.</p>}{episode.contextReport&&!dirty&&<><p className="muted small fanfic-context-last">Последняя сцена: {episode.contextReport.selectedMemory?.filter((d:any)=>d.included!==false).length||0} блоков памяти · {episode.contextReport.selectedLore?.filter((d:any)=>d.included!==false).length||0} записей лора{episode.contextReport.vectorStatus==='fallback'?' · векторный поиск недоступен':''}</p>{episode.contextReport.warnings?.map((warning:string,index:number)=><p key={index} className="fanfic-notice small" role="status">{warning}</p>)}</>}{episode.memory&&<Button disabled={locked||dirty} onClick={()=>{setMemorySnapshot(structuredClone(episode.memory));setMemoryEditing(true);}}>Проверить и исправить сводку серии</Button>}<div className="fanfic-memory-list">{episodes.filter(item=>item.memory).map(item=>{const earlier=item.season<episode.season||item.season===episode.season&&item.number<episode.number;return <details key={item.id} open={item.id===episode.id}><summary>{item.season}.{item.number} · {item.title}{item.needsReview?' · проверить':''}</summary><span className="fanfic-memory-caption">{item.needsReview||item.status!=='approved'?'Не используется: требуется утверждение':earlier?'Доступна для текущей серии':item.id===episode.id?'Память этой серии — для следующих серий':'Будущая серия — в текущий контекст не входит'}{item.memory.chunks?.length>1?` · ${item.memory.chunks.length} блоков`:''}</span><TextContent text={item.memory.summary||''}/>{item.memory.location&&<p><strong>Место: </strong>{item.memory.location}</p>}{item.memory.relationships?.length>0&&<p><strong>Отношения: </strong>{item.memory.relationships.join('; ')}</p>}{item.memory.openThreads?.length>0&&<p><strong>Незавершённые линии: </strong>{item.memory.openThreads.join('; ')}</p>}</details>;})}{!episodes.some(item=>item.memory)&&<p className="muted small">Утвердите готовый эпизод, чтобы сохранить сводку событий.</p>}</div></section>
          <section className="panel"><h3>Сохранённые версии</h3><div className="fanfic-version-list">{[...(episode.versions||[])].reverse().map((version:any,index:number)=><div className="fanfic-version" key={version.id}><span><strong>{version.label||version.title||`Версия ${(episode.versions?.length||0)-index}`}</strong><small>{new Date(version.createdAt).toLocaleString('ru-RU')}</small></span><Button disabled={locked||dirty} title="Восстановить эту версию" onClick={()=>void perform(async()=>{await api(episodePath(project.id,episode.id)+'/restore',{versionId:version.id,expectedRevision:episode.revision});notify('Версия восстановлена как черновик.');})}><Undo2 size={14}/></Button></div>)}{!episode.versions?.length&&<p className="muted small">Версии сохраняются при изменении текста.</p>}</div></section>
          <section className="panel"><h3>Иллюстрации</h3><Button disabled={locked||conflict||!content} onClick={()=>{setImageScope(selection.end>selection.start?'selection':'recent');setImagePrompt('');setImageSource(null);setFramePassport(null);setPassportDirty(false);setUsePassport(false);setImageOpen(true);void perform(async()=>{const result=await api(episodePath(project.id,episode.id)+'/frame-passport');if(sameDraftScope(draftRef.current,project.id,episode.id)){setFramePassport(result.passport);setPassportSource(result);setPassportStale(result.stale);setUsePassport(!!result.passport&&!result.stale&&result.passport.scope===(selection.end>selection.start?'selection':'recent')&&(result.passport.scope!=='selection'||result.passport.sceneExcerpt===content.slice(selection.start,selection.end)));}});}}><ImagePlus size={16}/>Создать с ComfyUI</Button><div className="fanfic-images">{images.map(image=><figure key={image.id}>{image.files?.map((_:any,index:number)=><a key={index} href={`/api/images/${encodeURIComponent(image.id)}/${index}`} target="_blank" rel="noreferrer"><img src={`/api/images/${encodeURIComponent(image.id)}/${index}`} alt="Иллюстрация к эпизоду" loading="lazy"/></a>)}{!image.files?.length&&<p className="muted small">{image.error||({queued:'В очереди ComfyUI',running:'Создаётся иллюстрация',cancelled:'Отменено',error:'Ошибка генерации'} as Record<string,string>)[image.status]||'Изображение готовится…'}</p>}<figcaption><details><summary>Промпт изображения</summary><p>{image.prompt}</p></details></figcaption></figure>)}</div></section>
          <section className="panel"><h3>Файлы произведения</h3><div className="fanfic-export"><Button disabled={locked} onClick={()=>void perform(async()=>{if(dirty)await saveDraft();downloadJSON(await api(projectPath(project.id)+'/export'),filename(project.title)+'.sas-fanfic.json');})}><Download size={15}/>Проект JSON</Button><Button disabled={locked} onClick={()=>exportBook(false)}>Текст TXT</Button><Button disabled={locked} onClick={()=>exportBook(true)}>Markdown</Button><Button danger disabled={locked} onClick={()=>setDeleting('episode')}><Trash2 size={15}/>Удалить эпизод</Button></div></section>
        </aside>
      </div>:<Empty title="Первый эпизод произведения" icon={<BookOpen size={34}/>}><p>Создайте эпизод и опишите, с чего начинается история.</p><Button primary disabled={locked} onClick={()=>setNewEpisode(true)}>Создать эпизод</Button></Empty>}
    </>:<Empty title="Место для вашей истории" icon={<BookOpen size={34}/>}><p>Задайте мир, выберите героев и пишите произведение по эпизодам. Локальная модель работает без интернета.</p><Button primary disabled={locked} onClick={()=>setSettings('new')}>Создать произведение</Button></Empty>}
    {settings&&<ProjectSettings key={settings==='new'?'new':project.id} project={settings==='edit'?project:null} state={state} locked={locked} onClose={()=>setSettings(null)} onCalibrate={settings==='edit'?()=>void perform(async()=>{await api(projectPath(project.id)+'/calibrate',{});notify('Модель выполняет пять контрольных заданий для фанфика.');}):undefined} onApplyProfile={value=>void perform(async()=>{await api(projectPath(project.id),profileUpdatePayload(project,value),'PATCH');notify('Предложенные профили применены к этому произведению.');})} onSave={data=>void perform(async()=>{const result=await api(settings==='new'?'/fanfic/projects':projectPath(project.id),data,settings==='new'?'POST':'PATCH');if(settings==='new')chooseProject(result.id);setSettings(null);notify('Настройки произведения сохранены.');})}/>}
    {contextPreview&&<Modal title="Контекст текущей серии" onClose={()=>setContextPreview(null)}><ContextInspector preview={contextPreview}/></Modal>}
    {editOpen&&proposal.proposal&&episode&&<Modal title="Предложение редактора" onClose={()=>setEditOpen(false)}><p className="muted small">{project.title} · {episode.season}.{episode.number} · изменяется {proposal.proposal.selectionEnd-proposal.proposal.selectionStart} символов. Остальной текст сохраняется.</p>{proposal.reason&&<p className="error-box" role="alert">{proposal.reason}</p>}<ProposalWarnings warnings={proposal.proposal.warnings||[]}/><div className="fanfic-edit-compare"><section><h3>Было</h3><TextContent text={proposal.proposal.original||''}/></section><section><h3>Предложено</h3><TextContent text={proposal.proposal.replacement||''}/></section></div><div className="fanfic-toolbar"><Button onClick={()=>setEditOpen(false)}>Решить позже</Button><Button danger disabled={locked} onClick={()=>void perform(async()=>{const result=await api(episodePath(project.id,episode.id)+'/edits/'+encodeURIComponent(proposal.proposal.id),{expectedRevision:episode.revision},'DELETE');const rebased=rebaseMetadataDraft(draftRef.current,project.id,episode,result.episode||result);if(rebased&&rebased!==draftRef.current)putDraft(rebased);setEditOpen(false);notify('Предложение отклонено. Исходный текст сохранён.');})}>Отклонить</Button><Button primary disabled={locked||!proposal.canApply} onClick={()=>void perform(async()=>{const result=await api(episodePath(project.id,episode.id)+'/edits/'+encodeURIComponent(proposal.proposal.id)+'/apply',{expectedRevision:episode.revision});if(sameDraftScope(draftRef.current,project.id,episode.id))putDraft(asDraft(project.id,result.episode||result));setEditOpen(false);notify('Правка принята. Память и последующие серии требуют проверки.');})}><Check size={15}/>Принять правку</Button></div></Modal>}
    {factsEditing&&episode&&memorySnapshot&&<FactEditor key={project.id+':'+episode.id} episode={{...episode,memory:memorySnapshot}} locked={locked} onClose={()=>setFactsEditing(false)} onSave={(changes,revision)=>void perform(async()=>{let expectedRevision=revision;for(const data of changes){const result=await api(episodePath(project.id,episode.id)+'/memory/facts',{...data,expectedRevision},'PATCH');expectedRevision=(result.episode||result).revision;}setFactsEditing(false);notify('Факты памяти сохранены.');})}/>}
    {memoryEditing&&episode&&memorySnapshot&&<MemoryEditor key={project.id+':'+episode.id} episode={{...episode,memory:memorySnapshot}} locked={locked} onClose={()=>setMemoryEditing(false)} onSave={(changes,revision)=>void perform(async()=>{let expectedRevision=revision;for(const data of changes){const result=await api(episodePath(project.id,episode.id)+'/memory',{...data,expectedRevision},'PATCH');expectedRevision=result.revision;}setMemoryEditing(false);notify('Сводка памяти сохранена.');})}/>}
    {material&&<Modal title={material.name||'Материал произведения'} onClose={()=>setMaterial(null)}><p className="muted small fanfic-snapshot-note">Сохранённая версия внутри «{project.title}».</p>{material.kind==='lore'?<div className="fanfic-reference-entries">{material.entries.map((entry:any)=><details key={entry.id}><summary>{entry.name||'Запись'} · {entry.enabled===false?'отключена':entry.constant?'постоянная':entry.vectorized?'векторный поиск':'по ключам'}</summary><TextContent text={entry.content}/>{entry.keys?.length>0&&<p className="muted small">Ключи: {entry.keys.join(', ')}</p>}</details>)}</div>:<div className="fanfic-reference-entries">{[['description','Описание'],['appearance','Внешность'],['personality','Характер'],['scenario','Сценарий']].filter(([key])=>material[key]).map(([key,label])=><section key={key}><h4>{label}</h4><TextContent text={material[key]}/></section>)}</div>}</Modal>}
    {newEpisode&&project&&<EpisodeCreator season={season||seasons.at(-1)||1} episodes={episodes} locked={locked} onClose={()=>setNewEpisode(false)} onCreate={data=>void perform(async()=>{const result=await api(projectPath(project.id)+'/episodes',data);setSeason('');chooseEpisode(result.id);setNewEpisode(false);})}/>}
    {deleting&&project&&<Modal title={deleting==='project'?'Удалить произведение?':'Удалить эпизод?'} onClose={()=>setDeleting(null)}><p>{deleting==='project'?'Все эпизоды, версии и память этого произведения будут удалены.':'Эпизод и его версии будут удалены. Более поздние эпизоды потребуется проверить.'}</p>{dirty&&<p className="fanfic-notice">В текущей серии есть несохранённые правки. Скачайте черновик перед удалением.</p>}<div className="fanfic-toolbar"><Button onClick={()=>setDeleting(null)}>Отмена</Button>{dirty&&<Button onClick={draftBackup}>Скачать черновик</Button>}<Button danger disabled={locked} onClick={()=>void perform(async()=>{if(deleting==='project'){await api(projectPath(project.id),undefined,'DELETE');for(const item of episodes){persistEpisodeDraft(sessionStorage,asDraft(project.id,item));sessionStorage.removeItem(fanficStorageKey('instruction',project.id,item.id));}chooseProject('');}else{await api(episodePath(project.id,episode.id),undefined,'DELETE');persistEpisodeDraft(sessionStorage,asDraft(project.id,episode));sessionStorage.removeItem(fanficStorageKey('instruction',project.id,episode.id));sessionStorage.removeItem('sas-fanfic-draft-'+episode.id);chooseEpisode('');}setDeleting(null);})}>Удалить</Button></div></Modal>}
    {discardingDraft&&episode&&<Modal title="Сбросить ручные правки?" onClose={()=>setDiscardingDraft(false)}><p>Будет открыт текст, сохранённый в произведении. Несохранённый черновик заменится этой версией.</p><div className="fanfic-toolbar"><Button onClick={()=>setDiscardingDraft(false)}>Отмена</Button><Button onClick={draftBackup}><Download size={15}/>Скачать черновик</Button><Button danger disabled={locked} onClick={()=>{putDraft(asDraft(project.id,episode));setDiscardingDraft(false);}}>Сбросить правки</Button></div></Modal>}
    {imageOpen&&project&&episode&&<Modal title="Иллюстрация эпизода" onClose={()=>setImageOpen(false)}><p className="muted small fanfic-snapshot-note">«{project.title}» · {episode.season}.{episode.number} · {episode.title}</p><Field label="Сцена для изображения"><select disabled={locked} value={imageScope} onChange={event=>{setImageScope(event.target.value as 'recent'|'selection');setUsePassport(false);setImagePrompt('');setImageSource(null);}}><option value="recent">Последняя сцена эпизода</option><option value="selection" disabled={selection.end<=selection.start}>Выделенный фрагмент текста</option></select></Field>{imageScope==='selection'&&<details className="fanfic-image-source" open><summary>Выделено {selection.end-selection.start} символов</summary>{selection.end-selection.start>16000&&<p className="error-box">Выберите для кадра фрагмент до 16 000 символов.</p>}<blockquote>{content.slice(selection.start,selection.end)}</blockquote></details>}<Field label="Что изобразить" hint="Выберите один момент, героев и желаемый ракурс."><textarea rows={3} maxLength={2000} disabled={locked} value={imageInstructions} onChange={event=>{setImageInstructions(event.target.value);setImagePrompt('');setImageSource(null);}} placeholder="Момент встречи героев у ворот города…"/></Field><Button disabled={locked||conflict||usePassport&&(passportIsStale||dirty)||imageScope==='selection'&&(selection.end<=selection.start||selection.end-selection.start>16000)} onClick={()=>void perform(async()=>{const saved=await saveDraft();const result=await api(episodePath(project.id,episode.id)+'/image-prompt',{instructions:imageInstructions,expectedRevision:saved.revision,usePassport:usePassport,...(usePassport&&currentPassport?{framePassport:{...currentPassport,scope:imageScope,sceneExcerpt:imageScope==='selection'?saved.content.slice(selection.start,selection.end):''}}:{}),...(imageScope==='selection'?{sceneExcerpt:saved.content.slice(selection.start,selection.end)}:{})});setImagePrompt(result.prompt);setImageSource(result);if(result.framePassport){setFramePassport(result.framePassport);setPassportSource(result);setPassportDirty(true);setPassportStale(false);setUsePassport(true);}})}><Sparkles size={16}/>Подготовить промпт</Button>{imageSource?.castNames?.length>0&&<p className="fanfic-draft-note">Герои кадра: {imageSource.castNames.join(', ')}</p>}{imageSource?.warnings?.map((warning:string,index:number)=><p key={index} className="fanfic-notice">{warning}</p>)}{dirty&&usePassport&&<p className="fanfic-notice">Сохраните ручные правки серии перед использованием паспорта кадра.</p>}<details className="fanfic-frame-passport" open={!!currentPassport}><summary>Паспорт кадра · герои и композиция</summary><p className="muted small">Сохраните внешность, одежду и ракурс для повторных иллюстраций этой серии. Изменение паспорта требует подготовки нового промпта.</p>{passportIsStale&&<p className="fanfic-notice">Текст серии изменился. Сверьте паспорт с текущей сценой и сохраните его заново.</p>}{currentPassport?<><div className="setting-toggle"><span>Использовать паспорт при подготовке</span><Toggle label="Использовать паспорт кадра" disabled={locked||passportIsStale||dirty} checked={usePassport} onChange={value=>{setUsePassport(value);setImagePrompt('');setImageSource(null);}}/></div><FramePassportEditor passport={currentPassport} locked={locked} onChange={changePassport}/><Button disabled={locked||dirty||(!passportDirty&&!passportIsStale)} onClick={()=>void perform(async()=>{const result=await api(episodePath(project.id,episode.id)+'/frame-passport',{passport:passportIsStale?{...currentPassport,sourceHash:undefined,sourceRevision:undefined,sceneExcerpt:imageScope==='selection'?content.slice(selection.start,selection.end):''}:currentPassport,expectedRevision:episode.revision,...(!passportIsStale&&passportSource?.sourceHash?{sourceHash:passportSource.sourceHash}:{})},'PUT');setFramePassport(result.passport);setPassportSource(result);setPassportDirty(false);setPassportStale(false);setUsePassport(true);notify('Паспорт кадра сохранён.');})}><Save size={15}/>{passportIsStale?'Подтвердить для текущего текста':'Сохранить паспорт'}</Button>{passportDirty&&<p className="muted small">Паспорт пока не сохранён в произведении.</p>}</>:<p className="muted small">Подготовьте промпт: модель предложит паспорт выбранной сцены.</p>}</details><Field label="Промпт для ComfyUI"><textarea rows={7} disabled={locked} value={imagePrompt} onChange={event=>setImagePrompt(event.target.value)} placeholder="Подготовьте промпт по выбранной сцене, затем при необходимости исправьте его."/></Field><p className="muted small">Workflow, модель и размер: {state.settings.comfy.model||'из workflow'} · {state.settings.comfy.width} × {state.settings.comfy.height}. Используются настройки ComfyUI.</p><div className="fanfic-toolbar"><Button primary disabled={locked||conflict||!imagePrompt.trim()} onClick={()=>void perform(async()=>{const saved=await saveDraft();await api(episodePath(project.id,episode.id)+'/images',{prompt:imagePrompt,expectedRevision:saved.revision,...(imageSource?.framePassport?{framePassport:imageSource.framePassport}:{}),...(imageSource?.sourceHash?{sourceHash:imageSource.sourceHash}:{})});setImageOpen(false);notify('Иллюстрация отправлена в ComfyUI.');})}>Создать изображение</Button></div></Modal>}
  </div>;
}

function ProposalWarnings({warnings}:{warnings:any[]}){
 return <>{warnings.map((warning,i)=><div key={i} className="fanfic-notice"><p>{typeof warning==='string'?warning:warning?.message||'Проверьте связность предложенной правки.'}</p>{typeof warning==='object'&&warning?.evidence?.map((quote:string,j:number)=><blockquote key={j}>{quote}</blockquote>)}{typeof warning==='object'&&warning?.suggestion&&<p className="small">{warning.suggestion}</p>}</div>)}</>;
}

function FramePassportEditor({passport,locked,onChange}:{passport:any;locked:boolean;onChange:(value:any)=>void}){
  const fields=[['moment','Момент'],['action','Действие'],['location','Окружение'],['camera','Ракурс и крупность'],['lighting','Освещение']];
  const subjects=passport.subjects||[];
  return <fieldset className="fanfic-form-fieldset" disabled={locked}>{fields.map(([key,label])=><Field key={key} label={label}><textarea rows={2} maxLength={key==='moment'||key==='action'?1800:1000} value={passport[key]||''} onChange={event=>onChange({...passport,[key]:event.target.value})}/></Field>)}{subjects.map((subject:any,i:number)=><details className="fanfic-frame-subject" key={subject.characterId||i} open><summary>{subject.name||'Участник кадра'}</summary><Field label="Имя"><input maxLength={120} value={subject.name||''} onChange={event=>onChange({...passport,subjects:subjects.map((s:any,j:number)=>j===i?{...s,name:event.target.value}:s)})}/></Field><Field label="Внешность"><textarea rows={3} maxLength={3000} value={subject.appearance||''} onChange={event=>onChange({...passport,subjects:subjects.map((s:any,j:number)=>j===i?{...s,appearance:event.target.value}:s)})}/></Field><Field label="Одежда"><textarea rows={2} maxLength={1500} value={subject.outfit||''} onChange={event=>onChange({...passport,subjects:subjects.map((s:any,j:number)=>j===i?{...s,outfit:event.target.value}:s)})}/></Field><Button danger onClick={()=>onChange({...passport,subjects:subjects.filter((_:any,j:number)=>j!==i)})}>Убрать из кадра</Button></details>)}<Button disabled={locked||subjects.length>=8} onClick={()=>onChange({...passport,subjects:[...subjects,{characterId:'',name:'',appearance:'',outfit:''}]})}><Plus size={14}/>Добавить участника кадра</Button></fieldset>;
}

function MemoryEditor({episode,locked,onClose,onSave}:{episode:any;locked:boolean;onClose:()=>void;onSave:(data:any[],revision:number)=>void}){
  const parts=episode.memory.chunks?.length?episode.memory.chunks:[episode.memory];
  const [revision]=useState(episode.revision),[original]=useState<any[]>(()=>structuredClone(parts));
  const [index,setIndex]=useState(0),[drafts,setDrafts]=useState<any[]>(()=>original.map(part=>({...part,relationships:(part.relationships||[]).join('\n'),openThreads:(part.openThreads||[]).join('\n')})));
  const data=drafts[index],stale=revision!==episode.revision;
  const setData=(value:any)=>setDrafts(current=>current.map((part,i)=>i===index?value:part));
  const lines=(value:string)=>value.split('\n').map(line=>line.trim()).filter(Boolean);
  const fields=['summary','location','relationships','openThreads'];
  const normalized=drafts.map((part,i)=>({chunkIndex:i,summary:part.summary,location:part.location||'',relationships:lines(part.relationships),openThreads:lines(part.openThreads)}));
  const changes=normalized.filter((part,i)=>JSON.stringify(fields.map(key=>part[key as keyof typeof part]))!==JSON.stringify(fields.map(key=>original[i][key]??(key==='location'?'':[]))));
  return <Modal title="Память серии · проверка фактов" onClose={onClose}><form onSubmit={event=>{event.preventDefault();if(!locked&&!stale)onSave(changes,revision);}}><p className="muted small fanfic-snapshot-note">Сверьте сводку с текстом серии. Переключение между блоками сохраняет ваши правки в этом окне. Сохраняются все изменённые блоки.</p>{stale&&<p className="error-box" role="alert">Серия или её память изменились в другом окне. Скопируйте свои правки, закройте окно и откройте актуальную память.</p>}<fieldset className="fanfic-form-fieldset" disabled={locked}>{drafts.length>1&&<Field label="Блок памяти"><select value={index} onChange={event=>setIndex(Number(event.target.value))}>{drafts.map((_:any,i:number)=><option key={i} value={i}>Часть {i+1} из {drafts.length}{changes.some(part=>part.chunkIndex===i)?' · изменена':''}</option>)}</select></Field>}<Field label="Сводка событий"><textarea required rows={6} maxLength={6000} value={data.summary} onChange={event=>setData({...data,summary:event.target.value})}/></Field><Field label="Место"><input maxLength={1000} value={data.location||''} onChange={event=>setData({...data,location:event.target.value})}/></Field><Field label="Отношения · по одному на строку" hint="До 20 кратких записей; не больше 800 символов в каждой."><textarea rows={3} maxLength={16020} value={data.relationships} onChange={event=>setData({...data,relationships:event.target.value})}/></Field><Field label="Незавершённые линии · по одной на строку" hint="До 20 кратких записей; завершённые цели удалите."><textarea rows={3} maxLength={16020} value={data.openThreads} onChange={event=>setData({...data,openThreads:event.target.value})}/></Field>{data.evidence&&<details className="fanfic-reference-entries"><summary>Цитаты из исходной серии</summary>{data.evidence.summary?.map((quote:string,i:number)=><blockquote key={i}>{quote}</blockquote>)}</details>}<details className="fanfic-reference-entries"><summary>Исходный текст серии</summary><TextContent text={episode.content}/></details></fieldset><div className="fanfic-toolbar"><Button onClick={onClose}>Отмена</Button><Button primary type="submit" disabled={locked||stale||!changes.length||normalized.some(part=>!part.summary?.trim()||part.relationships.length>20||part.openThreads.length>20||[...part.relationships,...part.openThreads].some(line=>line.length>800))}><Save size={15}/>Сохранить память{changes.length?` (${changes.length})`:''}</Button></div></form></Modal>;
}

function FactEditor({episode,locked,onClose,onSave}:{episode:any;locked:boolean;onClose:()=>void;onSave:(changes:any[],revision:number)=>void}){
  const parts=episode.memory.chunks?.length?episode.memory.chunks:[episode.memory];
  const [revision]=useState(episode.revision),[original]=useState<any[][]>(()=>parts.map((part:any)=>structuredClone(part.facts||[])));
  const [index,setIndex]=useState(0),[drafts,setDrafts]=useState<any[][]>(()=>original.map(facts=>facts.map(fact=>({...editableFact(fact),aliases:(fact.aliases||[]).join('\n')}))));
  const changes=drafts.map((facts,i)=>({chunkIndex:i,facts:factSavePayload(facts)})).filter((part,i)=>JSON.stringify(part.facts)!==JSON.stringify(original[i]));
  const stale=revision!==episode.revision;
  const change=(factIndex:number,patch:any)=>setDrafts(current=>current.map((facts,i)=>i===index?facts.map((fact,j)=>j===factIndex?{...fact,...patch}:fact):facts));
  const valid=drafts.every(facts=>facts.length<=12&&facts.every(fact=>fact.subject.trim()&&fact.predicate.trim()&&fact.value.trim()&&fact.aliases.split('\n').filter((line:string)=>line.trim()).length<=8&&fact.aliases.split('\n').every((line:string)=>line.trim().length<=160)));
  return <Modal title="Факты памяти серии" onClose={onClose}><form onSubmit={event=>{event.preventDefault();if(!locked&&!stale&&valid)onSave(changes,revision);}}><p className="muted small">У каждого факта сохраняется серия-источник. Цитаты не переписываются вместе с формулировкой. Новые факты будут отмечены как подтверждённые автором.</p>{stale&&<p className="error-box" role="alert">Серия изменилась. Скопируйте правки, затем откройте актуальную память; эта форма не перезапишет новую версию.</p>}<fieldset className="fanfic-form-fieldset" disabled={locked}>{drafts.length>1&&<Field label="Блок памяти"><select value={index} onChange={event=>setIndex(Number(event.target.value))}>{drafts.map((_,i)=><option key={i} value={i}>Часть {i+1}{changes.some(part=>part.chunkIndex===i)?' · изменена':''}</option>)}</select></Field>}<div className="fanfic-fact-editor">{drafts[index].map((fact,i)=><details key={fact.id||i} open={i===drafts[index].length-1}><summary>{factLabels[fact.type]||'Факт'} · {fact.subject||'Новый факт'}</summary><div className="form-grid"><Field label="Тип"><select value={fact.type} onChange={event=>change(i,{type:event.target.value})}>{Object.entries(factLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Кто или что"><input required maxLength={160} value={fact.subject} onChange={event=>change(i,{subject:event.target.value})}/></Field></div><Field label="Связь или свойство"><input required maxLength={160} value={fact.predicate} onChange={event=>change(i,{predicate:event.target.value})}/></Field><Field label="Установленный факт"><textarea required rows={3} maxLength={800} value={fact.value} onChange={event=>change(i,{value:event.target.value})}/></Field><Field label="Имена и обозначения · по одному на строку"><textarea rows={2} maxLength={1280} value={fact.aliases} onChange={event=>change(i,{aliases:event.target.value})}/></Field>{fact.evidence?.map((e:any,j:number)=><blockquote key={j}>{e.quote}</blockquote>)}<p className="muted small">{fact.authorConfirmed?'Подтверждён автором':'Извлечено моделью; сверено с цитатой. Проверьте предложенную связь.'}</p><Button danger onClick={()=>setDrafts(current=>current.map((facts,j)=>j===index?facts.filter((_,k)=>k!==i):facts))}><Trash2 size={14}/>Удалить факт</Button></details>)}</div><Button disabled={locked||drafts[index].length>=12} onClick={()=>setDrafts(current=>current.map((facts,i)=>i===index?[...facts,{type:'event',subject:'',predicate:'',value:'',aliases:'',authorConfirmed:true}]:facts))}><Plus size={15}/>Добавить факт автора</Button></fieldset><div className="fanfic-toolbar"><Button onClick={onClose}>Отмена</Button><Button type="submit" primary disabled={locked||stale||!valid||!changes.length}><Save size={15}/>Сохранить факты</Button></div></form></Modal>;
}

function ContextInspector({preview}:{preview:any}){
  const report={selectedMemory:[],selectedLore:[],...preview.report},reason:Record<string,string>={constant:'Всегда',keyword:'Ключи',vector:'Векторный поиск',recent:'Недавние события',chronology:'Хронология',semantic:'Смысл запроса',lexical:'Совпадение слов',participant:'Участник сцены',intent:'Тема запроса'};
  const used=report.selectedMemory.filter((d:any)=>d.included!==false),lore=report.selectedLore.filter((d:any)=>d.included!==false);
  return <div className="fanfic-context-inspector"><div className="fanfic-context-summary"><ShieldCheck size={24}/><div><strong>Память «{preview.projectTitle}» · {preview.season}.{preview.number}</strong><p>Другие фанфики, обычные чаты и будущие серии в этот запрос не входят.</p></div></div><div className="fanfic-context-metrics"><span><strong>{used.length}</strong> блоков памяти из {report.eligibleMemory}</span><span><strong>{lore.length}</strong> записей лора</span><span><strong>{report.estimatedTokens}</strong> ≈ токенов контекста</span></div><p className="muted small">Окно модели: {report.contextWindow} · Ответ: до {report.maxTokens} токенов · Векторный поиск: {({ready:'работает',disabled:'не используется',fallback:'недоступен, используется хронология'} as Record<string,string>)[report.vectorStatus]||report.vectorStatus}</p>{report.warnings?.map((warning:string,index:number)=><p key={index} className="fanfic-notice" role="status">{warning}</p>)}<h4>События прошлых серий</h4><div className="fanfic-context-records">{report.selectedMemory.map((d:any)=><div key={d.id}><span><strong>{d.title}</strong><small>{reason[d.reason]}{d.score!==undefined?` · сходство ${Math.round(d.score*100)}%`:''}</small></span><span className={'badge '+(d.included?'positive':'')}>{d.included?'В запросе':'Не поместился'}</span></div>)}{!report.selectedMemory.length&&<p className="muted small">Подходящей памяти ранних серий пока нет.</p>}</div>{report.queryPlan&&<details className="fanfic-query-plan"><summary>Что искалось для этой сцены</summary>{report.queryPlan.participants?.length>0&&<p className="muted small">Участники: {report.queryPlan.participants.map((p:any)=>p.name).join(', ')}</p>}{report.queryPlan.queries?.map((query:string,i:number)=><p key={i}>{query}</p>)}</details>}<h4>Выбранные факты</h4><div className="fanfic-context-records">{(report.selectedFacts||[]).map((fact:any,i:number)=><details key={fact.id||i}><summary>{fact.subject}{fact.authorConfirmed?' · '+fact.predicate:''} <span className="badge">{fact.included===false?'Не поместился':'В запросе'}</span></summary><p>{fact.value}</p><p className="muted small">{fact.authorConfirmed?'Подтверждён автором':'Извлечено моделью; сверено с цитатой'}</p><small>{(fact.reasons||[fact.reason]).map((r:string)=>reason[r]||r).join(' · ')}{fact.semanticScore!==undefined?` · векторное сходство ${Math.round(fact.semanticScore*100)}%`:''}</small>{fact.sourceEvidence?.map((e:any,j:number)=><blockquote key={j}>{e.quote}</blockquote>)}</details>)}{!report.selectedFacts?.length&&<p className="muted small">Структурированные факты не выбраны для этого запроса.</p>}</div><h4>Активный лор</h4><div className="fanfic-context-records">{report.selectedLore.map((d:any)=><div key={d.id}><span><strong>{d.name||'Запись'}</strong><small>{d.book} · {reason[d.reason]}{d.score!==undefined?` · сходство ${Math.round(d.score*100)}%`:''}</small></span><span className={'badge '+(d.included?'positive':'')}>{d.included?'В запросе':'Не поместился'}</span></div>)}{!report.selectedLore.length&&<p className="muted small">Нет совпадений по ключам или векторному поиску.</p>}</div><details className="fanfic-prompt-preview"><summary><FileText size={15}/>Предпросмотр запроса для продолжения</summary>{(preview.messages||[]).map((m:any,index:number)=><section key={index}><h4>{m.role==='system'?'Инструкция писателю':'Контекст серии'}</h4><pre>{m.content}</pre></section>)}</details></div>;
}

function ProjectSettings({project,state,locked,onClose,onSave,onCalibrate,onApplyProfile}:{project:any;state:StudioProps['state'];locked:boolean;onClose:()=>void;onSave:(value:any)=>void;onCalibrate?:()=>void;onApplyProfile?:(value:any)=>void}){
  const defaults={connectionId:'',style:'Живая художественная проза, конкретные детали и естественные диалоги',perspective:'Третье лицо',tense:'Прошедшее',genre:'',audience:'Общая аудитория',sceneCount:3,maxTokens:1200,temperature:0.8,continuityCheck:true,generationProfiles:{modelKind:'generic',stages:{}},vectorMemory:false,memoryTopK:8,memoryThreshold:.3,memoryRecentEpisodes:2,instructions:''};
  const ids=(items:any[])=>items?.map(item=>item.sourceId||item.originalId||item.id)||[];
  const [data,setData]=useState<any>({refreshSnapshots:false,title:project?.title||'',world:project?.world||'',canon:project?.canon||'',divergence:project?.divergence||'',characterIds:ids(project?.characters),personaIds:ids(project?.personas),lorebookIds:ids(project?.lorebooks),settings:{...defaults,...project?.settings,continuityCheck:project?!!project.settings?.continuityCheck:true}});
  const evaluation=project?.modelEvaluation;
  const calibratedSettings={...defaults,...project?.settings};
  const calibrationDirty=['connectionId','maxTokens','temperature'].some(key=>data.settings[key]!==calibratedSettings[key])||JSON.stringify(data.settings.generationProfiles)!==JSON.stringify(calibratedSettings.generationProfiles);
  const change=(key:string,value:any)=>setData((current:any)=>({...current,[key]:value}));
  const setting=(key:string,value:any)=>setData((current:any)=>({...current,settings:{...current.settings,[key]:value}}));
  const options=(library:any[],snapshots:any[])=>[...library,...(snapshots||[]).filter(item=>!library.some(source=>source.id===(item.sourceId||item.originalId||item.id))).map(item=>({...item,id:item.sourceId||item.originalId||item.id,name:item.name+' · сохранённая карточка'}))];
  const picker=(label:string,key:string,items:any[])=> <fieldset className="fanfic-card-picker"><legend>{label}</legend><div>{items.map(item=><label key={item.id}><input type="checkbox" checked={data[key].includes(item.id)} onChange={event=>change(key,event.target.checked?[...data[key],item.id]:data[key].filter((id:string)=>id!==item.id))}/><span>{item.name}</span></label>)}{!items.length&&<p className="muted small">Библиотека пока пуста.</p>}</div></fieldset>;
  return <Modal title={project?'Настройки произведения':'Новое произведение'} onClose={onClose}><form onSubmit={event=>{event.preventDefault();if(!locked)onSave(data);}}><fieldset disabled={locked} className="fanfic-form-fieldset"><Field label="Название"><input required autoFocus maxLength={200} value={data.title} onChange={event=>change('title',event.target.value)} placeholder="Название фанфика"/></Field><Field label="Мир произведения"><textarea rows={3} maxLength={12000} value={data.world} onChange={event=>change('world',event.target.value)} placeholder="Вселенная, эпоха и устройство мира"/></Field><Field label="Канон"><textarea rows={3} maxLength={12000} value={data.canon} onChange={event=>change('canon',event.target.value)} placeholder="Какие события, отношения и правила уже установлены"/></Field><Field label="Точка расхождения"><textarea rows={2} maxLength={8000} value={data.divergence} onChange={event=>change('divergence',event.target.value)} placeholder="С какого момента ваша история отличается от оригинала"/></Field>
      <details open><summary>Герои и лор</summary><p className="muted small fanfic-snapshot-note">Карточки сохраняются в произведении. Последующие изменения в библиотеке не изменят их автоматически.</p>{picker('Персонажи','characterIds',options(state.characters,project?.characters))}{picker('Персоны','personaIds',options(state.personas,project?.personas))}{picker('Лорбуки','lorebookIds',options(state.lorebooks,project?.lorebooks))}{project&&<Field label="Обновить выбранные карточки и лорбуки из библиотеки" hint="При сохранении заменит снимки материалами из библиотеки."><input type="checkbox" checked={data.refreshSnapshots} onChange={event=>change('refreshSnapshots',event.target.checked)}/></Field>}</details>
      <details open><summary>Повествование</summary><Field label="Стиль"><textarea rows={2} maxLength={2000} value={data.settings.style} onChange={event=>setting('style',event.target.value)}/></Field><div className="form-grid"><Field label="Точка зрения"><select value={data.settings.perspective} onChange={event=>setting('perspective',event.target.value)}>{[...new Set([data.settings.perspective,'Третье лицо','Первое лицо','Второе лицо','Несколько точек зрения'])].map(value=><option key={value}>{value}</option>)}</select></Field><Field label="Время"><select value={data.settings.tense} onChange={event=>setting('tense',event.target.value)}>{[...new Set([data.settings.tense,'Прошедшее время','Настоящее время'])].map(value=><option key={value}>{value}</option>)}</select></Field><Field label="Жанр"><input maxLength={200} value={data.settings.genre} onChange={event=>setting('genre',event.target.value)}/></Field><Field label="Аудитория"><select value={data.settings.audience} onChange={event=>setting('audience',event.target.value)}>{[...new Set([data.settings.audience,'Общая аудитория','Подростковая','Взрослая (18+)'])].map(value=><option key={value}>{value}</option>)}</select></Field></div><Field label="Постоянные авторские правила"><textarea rows={3} maxLength={4000} value={data.settings.instructions} onChange={event=>setting('instructions',event.target.value)} placeholder="Язык повествования, ограничения сюжета, особенности диалогов…"/></Field></details>
      <details><summary>Модель и генерация</summary><p className="muted small">Лимит и температура ниже относятся к базовому профилю. В Dense/MoE действуют параметры этапов; их можно переопределить отдельно.</p><Field label="Подключение"><select value={data.settings.connectionId} onChange={event=>setting('connectionId',event.target.value)}><option value="">Текущее подключение студии</option>{state.connections.filter(connection=>connection.id!=='sas-embedding').map(connection=><option key={connection.id} value={connection.id}>{connection.name} · {connection.model||'модель не выбрана'}</option>)}</select></Field><div className="form-grid"><Field label="Сцен в эпизоде"><input type="number" min={1} max={8} value={data.settings.sceneCount} onChange={event=>setting('sceneCount',Number(event.target.value))}/></Field><Field label="Токенов на сцену"><input type="number" min={256} max={4096} step={128} value={data.settings.maxTokens} onChange={event=>setting('maxTokens',Number(event.target.value))}/></Field><Field label="Температура"><input type="number" min={0} max={1.5} step={0.05} value={data.settings.temperature} onChange={event=>setting('temperature',Number(event.target.value))}/></Field></div><div className="setting-toggle"><span>Проверять связность после генерации</span><Toggle checked={data.settings.continuityCheck} disabled={locked} label="Проверять связность фанфика" onChange={value=>setting('continuityCheck',value)}/></div>{project&&<section className="fanfic-calibration"><h3>Проверка модели для фанфика</h3><p className="muted small">Пять коротких заданий проверяют прозу, план, факты, связность и локальную редактуру на сохранённом подключении. Один прогон не гарантирует качество длинного произведения.</p><Button disabled={locked||calibrationDirty||!onCalibrate} onClick={onCalibrate}><Sparkles size={15}/>Проверить модель для фанфика</Button>{calibrationDirty&&<p className="muted small">Сохраните новое подключение и параметры перед проверкой.</p>}{evaluation&&<><p className="muted small">Последняя проверка: {evaluation.model||'модель'} · контекст {evaluation.contextWindow} · {new Date(evaluation.createdAt).toLocaleString('ru-RU')}</p><div className="fanfic-calibration-results">{evaluation.stages?.map((stage:any)=><details key={stage.stage}><summary><span className={'badge '+(stage.status==='passed'?'positive':'')}>{stage.status==='passed'?'Пройдено':stage.status==='failed'?'Не пройдено':'Ошибка'}</span>{stageLabels[stage.stage]||stage.stage} · {(stage.elapsedMs/1000).toFixed(1)} с</summary>{stage.error&&<p className="error-box">{stage.error}</p>}{stage.charactersPerSecond!==undefined&&<p className="muted small">{stage.charactersPerSecond} символов/с за весь запрос, включая ожидание.</p>}{stage.checks&&Object.entries(stage.checks).map(([key,value])=><p className="muted small" key={key}>{calibrationCheckLabels[key]||'Условие '+(Object.keys(stage.checks).indexOf(key)+1)}: {value?'выполнено':'не выполнено'}</p>)}{stage.outputPreview&&<blockquote>{stage.outputPreview}</blockquote>}</details>)}</div>{evaluation.recommendation&&<><p className="muted small">{evaluation.recommendation.reason}</p><Button disabled={locked||!onApplyProfile} onClick={()=>{const value=evaluation.recommendation.generationProfiles;setting('generationProfiles',value);onApplyProfile?.(value);}}>Использовать предложенные профили</Button></>}</>}</section>}<details className="fanfic-profile-settings"><summary>Отдельные параметры этапов</summary><p className="muted small">Стартовый профиль помогает разделить художественную прозу и точную работу с фактами. Пустое поле использует параметры этапа. Эти настройки относятся к этому произведению.</p><Field label="Стартовый профиль модели"><select value={data.settings.generationProfiles?.modelKind||'generic'} onChange={event=>setting('generationProfiles',{...data.settings.generationProfiles,modelKind:event.target.value})}><option value="generic">Базовый · текущие настройки</option><option value="dense">Dense · последовательная работа</option><option value="moe">MoE · осторожная работа с фактами</option></select></Field>{Object.entries(stageLabels).map(([stage,label])=>{const profile=data.settings.generationProfiles?.stages?.[stage]||{};const setProfile=(key:string,value:string)=>{const next={...profile};if(value==='')delete next[key];else next[key]=Number(value);setting('generationProfiles',{...data.settings.generationProfiles,stages:{...data.settings.generationProfiles?.stages,[stage]:next}});};return <fieldset className="fanfic-stage-settings" key={stage}><legend>{label}</legend><div className="form-grid"><Field label="Максимум токенов"><input type="number" min={128} max={4096} step={64} value={profile.maxTokens??''} placeholder="Параметры этапа" onChange={event=>setProfile('maxTokens',event.target.value)}/></Field><Field label="Температура"><input type="number" min={0} max={1.5} step={0.05} value={profile.temperature??''} placeholder="Параметры этапа" onChange={event=>setProfile('temperature',event.target.value)}/></Field></div></fieldset>;})}</details></details><details><summary>Память и векторный поиск</summary><p className="muted small">Утверждённые серии образуют хронологию этого произведения. Векторный поиск находит связанные события из старых сезонов; последние серии сохраняются рядом с ними.</p><div className="setting-toggle"><span>Векторный поиск по памяти</span><Toggle disabled={locked} checked={data.settings.vectorMemory} label="Векторная память фанфика" onChange={value=>setting('vectorMemory',value)}/></div><div className="form-grid"><Field label="Последних серий всегда в памяти"><input type="number" min={1} max={10} value={data.settings.memoryRecentEpisodes} onChange={event=>setting('memoryRecentEpisodes',Number(event.target.value))}/></Field><Field label="Результатов векторного поиска"><input type="number" min={1} max={30} value={data.settings.memoryTopK} onChange={event=>setting('memoryTopK',Number(event.target.value))}/></Field><Field label="Минимальное сходство"><input type="number" min={0} max={1} step={0.05} value={data.settings.memoryThreshold} onChange={event=>setting('memoryThreshold',Number(event.target.value))}/></Field></div><p className="muted small">Используется embedding-модель из настроек SAS. Записи лорбука с включённой векторизацией ищутся независимо от переключателя памяти. При недоступности модели остаются хронология и ключевые слова.</p></details>
      </fieldset><div className="fanfic-toolbar"><Button onClick={onClose}>Закрыть</Button><Button type="submit" primary disabled={locked||!data.title.trim()}>{project?'Сохранить настройки':'Создать произведение'}</Button></div></form></Modal>;
}

function EpisodeCreator({season,episodes,locked,onClose,onCreate}:{season:number;episodes:any[];locked:boolean;onClose:()=>void;onCreate:(value:any)=>void}){
  const [data,setData]=useState({season,number:Math.max(0,...episodes.filter(item=>item.season===season).map(item=>item.number))+1,title:'',brief:''});
  return <Modal title="Новый эпизод" onClose={onClose}><form onSubmit={event=>{event.preventDefault();if(!locked)onCreate({...data,title:data.title.trim()||`Эпизод ${data.number}`});}}><fieldset className="fanfic-form-fieldset" disabled={locked}><div className="form-grid"><Field label="Сезон"><input type="number" required min={1} max={999} value={data.season} onChange={event=>{const value=Number(event.target.value);setData({...data,season:value,number:Math.max(0,...episodes.filter(item=>item.season===value).map(item=>item.number))+1});}}/></Field><Field label="Номер эпизода"><input type="number" required min={1} max={9999} value={data.number} onChange={event=>setData({...data,number:Number(event.target.value)})}/></Field></div><Field label="Название"><input autoFocus maxLength={200} value={data.title} onChange={event=>setData({...data,title:event.target.value})} placeholder={`Эпизод ${data.number}`}/></Field><Field label="Задание эпизода"><textarea rows={5} maxLength={16000} value={data.brief} onChange={event=>setData({...data,brief:event.target.value})} placeholder="Что должно произойти? Какая атмосфера и чем закончится эпизод?"/></Field></fieldset><div className="fanfic-toolbar"><Button onClick={onClose}>Отмена</Button><Button primary type="submit" disabled={locked}>Создать эпизод</Button></div></form></Modal>;
}
